import { NextResponse } from "next/server";
import { requestPasswordRecovery, isSupabaseAuthConfigured } from "@/src/auth/supabase";
import { checkRateLimit, RATE_LIMIT_TIERS } from "@/src/services/rate-limiter.service";
import { queryOne } from "@/src/db/client";
import { verifyTurnstileToken } from "@/src/auth/captcha";

const EMAIL_REGEX = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;

export async function POST(request: Request) {
  try {
    const ip =
      request.headers.get("cf-connecting-ip")?.trim() ||
      request.headers.get("x-forwarded-for")?.split(",").pop()?.trim() ||
      "unknown";
    const ipRateLimit = await checkRateLimit(`pwd-recover:ip:${ip}`, RATE_LIMIT_TIERS.auth);
    if (!ipRateLimit.allowed) {
      return NextResponse.json({ error: "Too many attempts. Please try again later." }, { status: 429 });
    }

    const body = await request.json().catch(() => ({}));
    const email = (body.email || "").toLowerCase().trim();

    if (!email || !EMAIL_REGEX.test(email)) {
      return NextResponse.json({ error: "A valid email address is required" }, { status: 400 });
    }

    const turnstileToken = body.turnstileToken || body.captchaToken || body["cf-turnstile-response"] || body.token;
    const isProd = process.env.NODE_ENV === "production" || process.env.VERCEL === "1";
    if (turnstileToken || isProd) {
      const captchaResult = await verifyTurnstileToken(turnstileToken || "", ip);
      if (!captchaResult.success) {
        return NextResponse.json(
          { error: captchaResult.error || "Security verification failed. Please try again." },
          { status: 400 }
        );
      }
    }

    if (!isSupabaseAuthConfigured()) {
      return NextResponse.json({ error: "Authentication service unavailable" }, { status: 503 });
    }

    // Role boundary defense: Customer, reseller, and supplier accounts may initiate recovery.
    // Privileged accounts (super_admin, internal_admin) and inactive accounts
    // must NOT initiate public password recovery or receive recovery tokens.
    let isPrivilegedOrInactive = false;
    try {
      const user = await queryOne<{ id: string; role: string; status: string }>(
        `SELECT id, role, status FROM app_users WHERE LOWER(email) = LOWER($1)`,
        [email]
      );
      if (user) {
        if (user.role === "super_admin" || user.role === "internal_admin") {
          isPrivilegedOrInactive = true;
        }
        if (user.status === "SUSPENDED" || user.status === "DISABLED" || user.status === "REJECTED") {
          isPrivilegedOrInactive = true;
        }
      }
    } catch {
      // On DB error, proceed safely without leaking
    }

    if (!isPrivilegedOrInactive) {
      const url = new URL(request.url);
      const origin = url.origin;
      const redirectTo = `${origin}/auth/callback?next=/reset-password`;

      try {
        await requestPasswordRecovery(email, redirectTo);
      } catch {
        // Generic response prevents account enumeration
      }
    }

    return NextResponse.json({
      success: true,
      message: "If an account exists for that email, a recovery link has been sent.",
    });
  } catch (err: any) {
    return NextResponse.json({ error: err.message || "Failed to process recovery request" }, { status: 500 });
  }
}

